/bin/bash -lc "python3 - <<'PY'
from datetime import datetime as D
from fractions import Fraction
from time import perf_counter
from tally import schedule as s, ledger, fields, intervals, duration, allocate
assert allocate.allocate_units(-5, [1,1,1]) == [-2,-2,-1]
assert allocate.allocate_units(2,[0,Fraction(1,4),0.75]) == [0,1,1]
assert duration.parse(' 2D 0h 4M 3s ') == 172803
for text in ('', '1s1h', '1h2H', '1 h','1h-2m'):
    try: duration.parse(text)
    except ValueError: pass
    else: raise AssertionError(text)
assert fields.parse_fields(' ; a=\" x\"\"=;y \"; ;b=') == {'a':' x\"=;y ', 'b':''}
for text in ('a', '=x','a=\"x', 'a=; a=b'):
    try: fields.parse_fields(text)
    except ValueError: pass
    else: raise AssertionError(text)
assert intervals.free_slots([(4,6),(-1,1),(5,8),(9,20)],0,10) == [(1,4),(8,9)]
assert ledger.bill([('Straße','15m'), (' STRASSE ','15m')], 5) == [('Straße',2)]
assert ledger.bill([('A','30m'), ('B','30m')], 1) == [('A',1),('B',0)]
assert ledger.bill([('A','0s')], -1) == [('A',0)]
for expr, start, expected in (
    ('0 0 L FEB ?',D(2024,2,1),D(2024,2,29)),
    ('0 0 ? * 5L',D(2026,11,1),D(2026,11,27)),
    ('0 0 ? * 7#5',D(2026,11,1),D(2026,11,29)),
    ('0 0 13 * Fri',D(2026,11,1),D(2026,11,13)),
    ('05/20 10 * JAN-MAR 6-7',D(2026,1,4,10,5),D(2026,1,4,10,25)),
    ('@hOuRlY',D(2026,1,1,10,0,1),D(2026,1,1,11)),
    ('* * * * *',D.max,None),
):
    assert s.next_run(expr,start) == expected, expr
    if expected: assert s.matches(expr,expected)
for expr in ('* * * * 7-0', '* * * * monL', '* * * * 7#6','1/00 * * * *','* * L/2 * *','@unknown','* * *\\n* *','? * * * *','0 0 ? * ?,2'):
    for fn in (s.matches,s.next_run):
        try: fn(expr,None)
        except ValueError: pass
        else: raise AssertionError(expr)
start = perf_counter()
assert s.next_run('0 0 31 FEB *', D(2026,1,1)) is None
print(f'Edge checks passed. Impossible schedule search took {perf_counter()-start:.4f}s.')
PY"

